package cn.zhuatech.salesagent.controller; import cn.zhuatech.salesagent.common.ApiResponse; import cn.zhuatech.salesagent.dto.SalesAgentDto.*; import cn.zhuatech.salesagent.service.SalesAgentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final SalesAgentService service;public OperationsAdminController(SalesAgentService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
